<script setup lang="ts">
import{ref,onMounted}from'vue';import{request,post}from'../api/client';import{ElMessageBox,ElMessage}from'element-plus'
interface Repository{id:string;name:string;url:string};interface Entry{id:string;name:string;version:string;author:string;description:string;packageUrl:string;digest:string}
const emit=defineEmits<{installed:[]}>();const repos=ref<Repository[]>([]),entries=ref<Entry[]>([]),selected=ref(''),name=ref(''),url=ref(''),busy=ref(false),error=ref(''),preview=ref<any>(null),entry=ref<Entry|null>(null),open=ref(false)
async function load(){try{repos.value=await request('/plugin-market/repositories')}catch(e){error.value=String(e)}}
async function browse(){busy.value=true;entries.value=[];error.value='';try{entries.value=await request(`/plugin-market/repositories/${selected.value}/catalog`)}catch(e){error.value=String(e)}finally{busy.value=false}}
async function add(){busy.value=true;error.value='';try{await post('/plugin-market/repositories',{name:name.value,url:url.value});name.value='';url.value='';await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function remove(repo:Repository){try{await ElMessageBox.confirm('删除仓库配置？不会卸载已安装插件。','删除插件仓库',{confirmButtonText:'确认删除',cancelButtonText:'取消'});await request(`/plugin-market/repositories/${repo.id}?confirm=true`,{method:'DELETE'});await load();entries.value=[]}catch(e){if(e instanceof Error)error.value=e.message}}
async function download(item:Entry){busy.value=true;error.value='';entry.value=item;try{preview.value=await post('/plugin-market/package',{repositoryId:selected.value,pluginId:item.id});open.value=true}catch(e){error.value=String(e)}finally{busy.value=false}}
async function install(){if(!entry.value||!preview.value)return;busy.value=true;try{const installed=await request<any[]>('/plugins');await post('/plugin-market/package',{repositoryId:selected.value,pluginId:entry.value.id,digest:preview.value.digest,revision:installed.find(x=>x.manifest.id===entry.value?.id)?.revision??0,confirm:true});open.value=false;ElMessage.success('市场插件已安装，当前停用');emit('installed')}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="panel section-gap"><div class="panel-title"><h2>插件市场</h2><span class="muted">本程序插件仓库 · HTTPS公开清单</span></div><p class="field-hint">参考MoviePilot的仓库、版本、预览、安装与升级流程；不安装其Python包。插件默认停用，版本变化须核对并确认；不自动更新。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><form class="market-add" @submit.prevent="add"><label>仓库名称<el-input v-model="name" aria-label="插件仓库名称" maxlength="100"/></label><label>清单URL<el-input v-model="url" aria-label="插件仓库URL" placeholder="https://example.com/plugins/index.json"/></label><el-button type="primary" native-type="submit" :loading="busy" :disabled="!name||!url">添加仓库</el-button></form><div v-for="repo in repos" :key="repo.id" class="market-repo"><el-button @click="selected=repo.id;browse()">浏览 {{repo.name}}</el-button><code>{{repo.url}}</code><el-button type="danger" plain :disabled="repo.id==='official'" @click="remove(repo)">移除仓库</el-button></div><div class="market-grid"><article v-for="item in entries" :key="item.id" class="note-panel"><h3>{{item.name}}</h3><p>{{item.author}} · {{item.version}}</p><p>{{item.description}}</p><el-button :loading="busy" @click="download(item)">预览安装 / 升级</el-button></article></div><p v-if="!repos.length" class="field-hint">尚未添加仓库。可先安装本仓库examples/plugins的ZIP示例；清单格式见插件开发说明。</p></section><el-dialog v-model="open" title="市场插件安装预览" width="min(760px,94vw)"><h2>{{preview?.manifest.name}}</h2><p>版本 {{preview?.manifest.version}} · 运行方式 {{preview?.manifest.runtime}}</p><p>出站目标：{{preview?.manifest.outbound?.join('、')||'无'}}</p><p>宿主权限：{{preview?.manifest.permissions?.join('、')||'无'}}</p><code>{{preview?.digest}}</code><pre>{{preview?.readme}}</pre><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="busy" @click="install">确认安装或升级</el-button></template></el-dialog></template>
<style scoped>.market-add{display:grid;grid-template-columns:1fr 2fr auto;gap:12px;align-items:end;margin:16px 0}.market-add label{display:grid;gap:8px}.market-repo{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0}.market-repo code{overflow-wrap:anywhere;flex:1}.market-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}@media(max-width:760px){.market-add{grid-template-columns:1fr}}</style>
